import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [form, setForm] = useState({ name: "", phone: "", address: "" });
  return (
    <View style={styles.screen}>
      <Text style={styles.title}>Хүргэлтийн хаяг</Text>
      <TextInput nativeID="name" style={styles.input} placeholder="Хүлээн авагчийн нэр"
        value={form.name} onChangeText={(v) => setForm({ ...form, name: v })} />
      <TextInput nativeID="phone" style={styles.input} placeholder="Утас" keyboardType="numeric"
        value={form.phone} onChangeText={(v) => setForm({ ...form, phone: v })} />
      {/* энд бичнэ үү: хаягийн талбар (nativeID="address") ба бүрэн preview нэм */}
      <Text nativeID="summary" style={styles.summary}>{form.name}, {form.phone}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12 },
  title: { fontSize: 22, fontWeight: "bold" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  summary: { fontSize: 15, color: "#334155", marginTop: 8 },
});

registerRootComponent(App);

